import { useEffect, useRef, useState } from 'react';
import { api, type Product, type ProductListingResponse } from '../api';
import { Badge, ErrorBox, Loading, Panel, money, shortDate } from '../components/Ui';
import ProductBuilder from './ProductBuilder';
import Products from './Products';
import Bookings from './Bookings';
import Payouts from './Payouts';
import Onboarding from './Onboarding';
import ProductImportModal, { downloadProductImportTemplate, downloadRateUpdateImportTemplate } from '../components/product-import/ProductImportModal';

type Departure = { id: string; bookingCode: string; serviceDate: string; time: string; pax: number; status: string; product: string; option: string; meetingPoint: string; manifestUrl: string };
type DashboardSummary = { bookingsToday: number; guestsToday: number; nextSevenDays: number; guestsNextSevenDays?: number; vendorNetEarningsMtd: number; vendorNetEarningsMtdChangePercent?: number | null; nextPayout: { amount: number; dueDate: string; currency?: string } | null; payoutAccount?: { masked: string | null; bankName: string | null; currency: string | null; verificationStatus: string }; pendingBookings: number; cancellationRate: number; listings: number; liveListings: number; draftListings: number; rejectedListings: number; expiredDocuments?: number; documentsExpiring: number; nearestExpiringDocument?: { type: string; expiresAt: string } | null; responseTimeMinutes: number | null; readinessScore: number; vendorActionRequiredBookings?: number; manualReviewPendingBookings?: number; legacyPendingBookings?: number; qualityIssueCount?: number; reviewsToReply?: number; averageReviewRatingMtd?: number | null; recentBookings: Array<Record<string, any>>; upcomingDepartures: Array<Record<string, any>>; todayDepartures: Departure[] };
type Trend = { days: Array<{ date: string; bookings: number; guests: number; revenue: number }> };
const errorText = (error: unknown) => error instanceof Error ? error.message : String(error);
const VENDOR_BASE = import.meta.env.BASE_URL === '/' ? '' : import.meta.env.BASE_URL.replace(/\/$/, '');
const vendorHref = (path: string) => `${VENDOR_BASE}${path}`;

function PageHeader({ eyebrow = '', title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) {
  return <header className="partner-page-header"><div>{eyebrow && <span className="partner-eyebrow">{eyebrow}</span>}<h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</header>;
}

export function PartnerDashboard({ onAddProduct, greetingName, businessName }: { onAddProduct?: () => void; greetingName?: string; businessName?: string }) {
  const [summary, setSummary] = useState<DashboardSummary | null>(null); const [trend, setTrend] = useState<Trend | null>(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [manifestDownloading, setManifestDownloading] = useState(false);
  useEffect(() => { let active = true; Promise.all([api.request<DashboardSummary>('/dashboard/summary'), api.request<Trend>('/dashboard/bookings-trend')]).then(([s, t]) => { if (active) { setSummary(s); setTrend(t); } }).catch((e) => { if (active) setError(errorText(e)); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, []);
  async function downloadManifest(departure: Departure) {
    setManifestDownloading(true);
    setError('');
    try {
      const blob = await api.blob(departure.manifestUrl.replace(/^\/api/, ''));
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `manifest-${departure.serviceDate}.csv`;
      anchor.click();
      window.setTimeout(() => URL.revokeObjectURL(url), 0);
    } catch (e) {
      setError(errorText(e));
    } finally {
      setManifestDownloading(false);
    }
  }
  const now = new Date(); const greeting = now.getHours() < 12 ? 'Good morning' : now.getHours() < 17 ? 'Good afternoon' : 'Good evening';
  const dashboardTitle = `${greeting}, ${(greetingName || 'there').trim().split(/\s+/)[0]}`;
  const dashboardDate = new Intl.DateTimeFormat('en-GB', { weekday: 'long', day: 'numeric', month: 'short', year: 'numeric' }).format(now);
  const dashboardDescription = [dashboardDate, businessName].filter(Boolean).join(' · ');
  const earningsMonth = new Intl.DateTimeFormat('en', { month: 'short' }).format(now);
  if (loading) return <Loading text="Loading your business overview…" />;
  if (error || !summary) return <><PageHeader eyebrow="" title={dashboardTitle} description={dashboardDescription} />{error && <ErrorBox error={error} />}</>;
  const days = trend?.days || []; const max = Math.max(1, ...days.map((day) => day.bookings)); const trendBookings = days.reduce((total, day) => total + day.bookings, 0); const trendGuests = days.reduce((total, day) => total + day.guests, 0);
  const expiringDocumentName: Record<string, string> = { PUBLIC_LIABILITY_INSURANCE: 'Public liability insurance', GSTIN: 'GST registration', PAN: 'PAN document', TRADE_LICENSE: 'Trade licence', TOURISM_REGISTRATION: 'Tourism registration', VEHICLE_PERMIT: 'Vehicle permit', BOAT_LICENSE: 'Boat licence', ADVENTURE_WATER_SPORTS_LICENSE: 'Adventure or water sports licence', FSSAI_LICENSE: 'FSSAI licence' };
  return <div className="partner-dashboard-page"><PageHeader eyebrow="" title={dashboardTitle} description={dashboardDescription} action={<div className="partner-page-actions"><a className="btn" href={vendorHref('/vendor/bookings')}>Redeem voucher</a><button className="btn primary" onClick={onAddProduct}>+ Add product</button></div>} />
    {summary.nearestExpiringDocument && <a className="partner-note warning partner-expiry-note" href={vendorHref('/vendor/onboarding')}><strong>{expiringDocumentName[summary.nearestExpiringDocument.type] || summary.nearestExpiringDocument.type.replaceAll('_', ' ')} expires on {shortDate(summary.nearestExpiringDocument.expiresAt)}.</strong><span>Upload a renewed document in Business profile &amp; KYC.</span></a>}
    <div className="kpi-row four"><div className="kpi-card"><span>Guests today</span><strong>{summary.guestsToday}</strong><small>{summary.bookingsToday} bookings · {summary.todayDepartures.length} departures</small></div><div className="kpi-card"><span>Next 7 days</span><strong>{summary.guestsNextSevenDays ?? summary.nextSevenDays}</strong><small>guests booked</small></div><div className="kpi-card"><span>You receive · {earningsMonth}</span><strong>{money(summary.vendorNetEarningsMtd)}</strong><small>{summary.vendorNetEarningsMtdChangePercent == null ? 'Vendor payable on confirmed and completed bookings · prior-period comparison unavailable' : `${summary.vendorNetEarningsMtdChangePercent > 0 ? '+' : ''}${summary.vendorNetEarningsMtdChangePercent.toFixed(0)}% vs same period last month`}</small></div><div className="kpi-card"><span>Next payout</span><strong>{summary.nextPayout ? money(summary.nextPayout.amount, summary.nextPayout.currency) : '—'}</strong><small>{summary.nextPayout ? `Due ${shortDate(summary.nextPayout.dueDate)}${summary.payoutAccount?.masked ? ` · to ${[summary.payoutAccount.bankName, summary.payoutAccount.masked].filter(Boolean).join(' ')}` : ''}` : 'No payout scheduled'}</small></div></div>
    <div className="partner-dashboard-grid"><Panel title="Needs your action"><div className="partner-task-list">
      {(summary.vendorActionRequiredBookings || 0) > 0 && <a className="partner-task urgent" href={vendorHref('/vendor/bookings')}><b>{summary.vendorActionRequiredBookings} bookings waiting for you to accept</b><span>Review and respond before the confirmation deadline.</span></a>}
      {(summary.manualReviewPendingBookings || 0) > 0 && <a className="partner-task" href={vendorHref('/vendor/bookings')}><b>{summary.manualReviewPendingBookings} bookings awaiting platform review</b><span>Track these bookings while the operations team completes its review.</span></a>}
      {(summary.legacyPendingBookings || 0) > 0 && <a className="partner-task" href={vendorHref('/vendor/bookings')}><b>{summary.legacyPendingBookings} bookings still pending confirmation</b><span>Open bookings to check their latest status.</span></a>}
      {(summary.expiredDocuments || 0) > 0 && <a className="partner-task urgent" href={vendorHref('/vendor/onboarding')}><b>{summary.expiredDocuments} verified documents expired</b><span>Upload renewed documents in Business profile &amp; KYC. Products pause until required insurance is verified again.</span></a>}
      {summary.documentsExpiring > 0 && <a className="partner-task warning" href={vendorHref('/vendor/onboarding')}><b>{summary.documentsExpiring} verified documents nearing expiry</b><span>Upload renewed documents in Business profile &amp; KYC.</span></a>}
      {summary.draftListings > 0 && <a className="partner-task warning" href={vendorHref('/vendor/products')}><b>{summary.draftListings} product drafts need attention</b><span>Continue editing and submit completed products for review.</span></a>}
      {(summary.reviewsToReply || 0) > 0 && <a className="partner-task" href={vendorHref('/vendor/reports')}><b>{summary.reviewsToReply} new reviews to reply to</b><span>{summary.averageReviewRatingMtd == null ? 'Review recent guest feedback.' : `Average rating this month: ${summary.averageReviewRatingMtd.toFixed(1)}`}</span></a>}
      {(summary.qualityIssueCount || 0) > 0 && <a className="partner-task warning" href={vendorHref('/vendor/products')}><b>{summary.qualityIssueCount} product quality items need attention</b><span>Review product feedback and update the affected listings.</span></a>}
      {!summary.vendorActionRequiredBookings && !summary.manualReviewPendingBookings && !summary.legacyPendingBookings && !summary.expiredDocuments && !summary.documentsExpiring && !summary.draftListings && !summary.reviewsToReply && !summary.qualityIssueCount && <div className="partner-empty-inline"><b>All caught up</b><span>There are no urgent tasks right now.</span></div>}
    </div></Panel><Panel title="Today’s departures" action={summary.todayDepartures[0] ? <button className="btn small" disabled={manifestDownloading} onClick={() => void downloadManifest(summary.todayDepartures[0])}>{manifestDownloading ? 'Downloading…' : 'Download manifest'}</button> : undefined}><div className="table-wrap"><table><thead><tr><th>Time</th><th>Product</th><th className="r">Guests</th><th>Status</th></tr></thead><tbody>{summary.todayDepartures.map((row) => <tr key={row.id}><td className="mono">{row.time || '—'}</td><td><b>{row.product}</b><div className="muted">{row.meetingPoint || row.option || '—'}</div></td><td className="r">{row.pax}</td><td><Badge value={row.status} /></td></tr>)}</tbody></table></div>{!summary.todayDepartures.length && <div className="empty">No departures scheduled for today.</div>}</Panel>
      <Panel title="Bookings, last 14 days"><div className="partner-trend-legend">By booking date · {trendBookings} bookings · {trendGuests} guests</div><div className="partner-trend-chart" aria-label="Daily booking trend">{days.map((day) => <div key={day.date} title={`${shortDate(day.date)}: ${day.bookings} bookings`}><i style={{ height: `${Math.max(day.bookings ? 8 : 2, day.bookings / max * 100)}%` }} /><small>{new Date(`${day.date}T00:00:00`).getDate()}</small></div>)}</div>{days.length > 1 && <small>{shortDate(days[0].date)} – {shortDate(days[days.length - 1].date)}</small>}</Panel>
    </div><div className="partner-dashboard-grid"><Panel title="Products"><p><b>{summary.liveListings}</b> live · <b>{summary.draftListings}</b> drafts · <b>{summary.rejectedListings}</b> need changes</p><button className="btn" onClick={onAddProduct}>Create a product</button></Panel><Panel title="Account health"><p>Profile readiness <b>{summary.readinessScore}%</b></p><p>{summary.pendingBookings} bookings need attention · {summary.documentsExpiring} documents nearing expiry</p><p>{summary.qualityIssueCount || 0} open quality items</p></Panel></div>
  </div>;
}

export function PartnerProductsPage({ onEditRoute, onBulkUploadRoute, onAddProductRoute }: { onEditRoute?: (id: string) => void; onBulkUploadRoute?: () => void; onAddProductRoute?: () => void }) { return <Products onEditRoute={onEditRoute} onBulkUploadRoute={onBulkUploadRoute} onAddProductRoute={onAddProductRoute} />; }
export function PartnerEditProductPage({ productId, onDone, onChanged }: { productId: string; onDone: () => void; onChanged: () => void }) { return <ProductBuilder key={productId} product={{ id: productId } as Product} fullPage onDone={onDone} onChanged={onChanged} />; }
export function PartnerAddProductPage({ onDone, onChanged }: { onDone: () => void; onChanged: () => void }) { return <ProductBuilder fullPage onDone={onDone} onChanged={onChanged} />; }
export function PartnerBookingsPage() { return <Bookings />; }
export function PartnerPaymentsPage() { return <Payouts />; }
export function PartnerOnboardingPage({ onNavigate, onStatusChange }: { onNavigate?: (page: 'products') => void; onStatusChange?: (status: string) => void }) { return <Onboarding onNavigate={onNavigate} onStatusChange={onStatusChange} />; }

export function PartnerBulkUploadPage() {
  const [open, setOpen] = useState(false); const [notice, setNotice] = useState('');
  return <><PageHeader title="Bulk upload" description="Load many products or rate changes from one spreadsheet. Rows are validated before anything is saved." />
    <div className="partner-bulk-steps">
      <Panel className="partner-bulk-step"><span className="partner-bulk-step-label">Step 1</span><h3>Download template</h3><p>One sheet each for Products, Options, Ticket types, Rates, Time slots. Products link by product code.</p><div className="partner-bulk-actions"><button className="btn small" onClick={downloadProductImportTemplate}>Product template</button><button className="btn small" onClick={downloadRateUpdateImportTemplate}>Rate update template</button></div></Panel>
      <Panel className="partner-bulk-step"><span className="partner-bulk-step-label">Step 2</span><h3>Upload file</h3><p>.xlsx or .csv, up to 2,000 rows. Choose create new or update existing.</p><button className="btn small primary" onClick={() => setOpen(true)}>Validate sample file</button></Panel>
      <Panel className="partner-bulk-step"><span className="partner-bulk-step-label">Step 3</span><h3>Fix &amp; import</h3><p>Valid rows import as Draft. Download the error file, fix, and re-upload only those rows.</p>{notice && <p role="status">{notice}</p>}</Panel>
    </div>
    {open && <ProductImportModal allowRateUpdates onClose={() => setOpen(false)} onComplete={(id, count, status, failure, importType) => { setOpen(false); if (importType === 'RATES') { setNotice(status === 'PARTIAL' ? `Rate updates stopped at product ${failure}; ${count} product groups were updated. Upload only the remaining rows after resolving the issue.` : `Rates updated for ${count} products.`); return; } if (!id) return; setNotice(status === 'PARTIAL' ? `Import stopped at product ${failure}; ${count} product drafts were saved. Save only the failed product rows into a new file before retrying.` : `Import created ${count} product draft${count === 1 ? '' : 's'}. Opening the first draft for review…`); window.history.pushState({}, '', vendorHref(`/vendor/products/${encodeURIComponent(id)}/edit`)); window.dispatchEvent(new PopStateEvent('popstate')); }} />}</>;
}

type Promotion = { id: string; name: string; productId: string; productName: string; promotionType: string; discountPercent: number; discountAmount?: number | null; conditionValue?: number | null; startsAt: string | null; endsAt: string | null; bookingStartsAt?: string | null; bookingEndsAt?: string | null; bookings: number | null; sales: number | null; active: boolean; draft?: boolean; impactTrackingAvailable?: boolean; fundingOwner?: string; validWeekdays?: string[]; stackWithPlatform?: boolean; maxDiscountedBookings?: number | null };
export function PartnerPromotionsPage() {
  const [rows, setRows] = useState<Promotion[]>([]); const [products, setProducts] = useState<ProductListingResponse['items']>([]); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const formRef = useRef<HTMLDivElement>(null);
  const [form, setForm] = useState({ name: '', productIds: [] as string[], promotionType: 'PERCENTAGE_OFF', discountPercent: '10', discountAmount: '', conditionValue: '', startsAt: '', endsAt: '', bookingStartsAt: '', bookingEndsAt: '', validWeekdays: [] as string[], maxDiscountedBookings: '', stackWithPlatform: false }); const [editingDraftId, setEditingDraftId] = useState('');
  const [weekdayPreset, setWeekdayPreset] = useState<'ALL' | 'WEEKDAYS' | 'WEEKENDS' | 'CUSTOM'>('ALL');
  async function load() { setLoading(true); setError(''); try { const [promos, listing] = await Promise.all([api.request<Promotion[]>('/vendor/promotions'), api.request<ProductListingResponse>('/products/listing?limit=100')]); setRows(promos); setProducts(listing.items || []); } catch (e) { setError(errorText(e)); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  const needsCondition = ['EARLY_BIRD', 'LAST_MINUTE', 'GROUP_DISCOUNT'].includes(form.promotionType);
  const weekdaysValid = weekdayPreset !== 'CUSTOM' || form.validWeekdays.length > 0;
  const typeOptions = [['PERCENTAGE_OFF','Percentage off','Save a percentage on selected dates.'],['FLAT_OFF','Flat amount off','Take a fixed amount off each booking.'],['EARLY_BIRD','Early bird','Reward bookings made ahead of the activity.'],['LAST_MINUTE','Last minute','Discount near the activity date.'],['GROUP_DISCOUNT','Group discount','Discount bookings above a guest threshold.']];
  const selectedPreview = products.find((product) => form.productIds.includes(product.id));
  const currentPrice = selectedPreview?.startingPrice == null ? null : Number(selectedPreview.startingPrice);
  const promoPrice = currentPrice == null ? null : Math.max(0, currentPrice - (form.promotionType === 'FLAT_OFF' ? Number(form.discountAmount || 0) : currentPrice * Number(form.discountPercent || 0) / 100));
  function promotionPayload(draft: boolean) { return { ...form, discountPercent: form.promotionType === 'FLAT_OFF' ? 0 : Number(form.discountPercent), discountAmount: form.promotionType === 'FLAT_OFF' ? Number(form.discountAmount) : undefined, conditionValue: needsCondition ? Number(form.conditionValue) : undefined, maxDiscountedBookings: form.maxDiscountedBookings ? Number(form.maxDiscountedBookings) : undefined, bookingStartsAt: form.bookingStartsAt || undefined, bookingEndsAt: form.bookingEndsAt || undefined, draft }; }
  async function persistPromotion(draft: boolean) { setBusy(true); setError(''); try { const payload = promotionPayload(draft); if (editingDraftId) await api.request(`/vendor/promotions/${editingDraftId}`, { method: 'PATCH', body: JSON.stringify(payload) }); else await api.request('/vendor/promotions', { method: 'POST', body: JSON.stringify(payload) }); setEditingDraftId(''); setForm({ name: '', productIds: [], promotionType: 'PERCENTAGE_OFF', discountPercent: '10', discountAmount: '', conditionValue: '', startsAt: '', endsAt: '', bookingStartsAt: '', bookingEndsAt: '', validWeekdays: [], maxDiscountedBookings: '', stackWithPlatform: false }); setWeekdayPreset('ALL'); await load(); } catch (e) { setError(errorText(e)); } finally { setBusy(false); } }
  async function savePromotion(event: React.FormEvent) { event.preventDefault(); await persistPromotion(false); }
  function editDraft(row: Promotion) { const day = row.validWeekdays || []; setEditingDraftId(row.id); setForm({ name: row.name, productIds: [row.productId], promotionType: row.promotionType, discountPercent: String(row.discountPercent || 10), discountAmount: row.discountAmount == null ? '' : String(row.discountAmount), conditionValue: row.conditionValue == null ? '' : String(row.conditionValue), startsAt: row.startsAt?.slice(0, 10) || '', endsAt: row.endsAt?.slice(0, 10) || '', bookingStartsAt: row.bookingStartsAt?.slice(0, 10) || '', bookingEndsAt: row.bookingEndsAt?.slice(0, 10) || '', validWeekdays: day, maxDiscountedBookings: row.maxDiscountedBookings == null ? '' : String(row.maxDiscountedBookings), stackWithPlatform: Boolean(row.stackWithPlatform) }); setWeekdayPreset(!day.length ? 'ALL' : day.length === 5 && ['MON','TUE','WED','THU','FRI'].every((value) => day.includes(value)) ? 'WEEKDAYS' : day.length === 2 && ['SAT','SUN'].every((value) => day.includes(value)) ? 'WEEKENDS' : 'CUSTOM'); formRef.current?.scrollIntoView({ behavior: 'smooth' }); }
  async function toggle(row: Promotion) { setError(''); try { await api.request(`/vendor/promotions/${row.id}`, { method: 'PATCH', body: JSON.stringify({ active: !row.active }) }); await load(); } catch (e) { setError(errorText(e)); } }
  if (loading) return <Loading />;
  return <>
    <PageHeader title="Promotions" description="Discounts you fund to fill slots. Customers see them as a saving on the listing." action={<button className="btn primary" type="button" onClick={() => { formRef.current?.scrollIntoView({ behavior: 'smooth' }); formRef.current?.querySelector('input')?.focus({ preventScroll: true }); }}>+ New promotion</button>} />
    {error && <ErrorBox error={error} />}
    <div className="table-wrap partner-promotion-list"><table><thead><tr><th>Promotion</th><th>Discount</th><th>Products</th><th>When</th><th className="r">Bookings</th><th className="r">Sales</th><th>Status</th></tr></thead><tbody>{rows.map((row) => <tr key={row.id}><td>{row.name}</td><td>{row.promotionType === 'FLAT_OFF' ? money(row.discountAmount || 0) : `${row.discountPercent}%`}{row.conditionValue ? ` · condition ${row.conditionValue}` : ''}</td><td>{row.productName}</td><td>{row.startsAt && row.endsAt ? `${shortDate(row.startsAt)} – ${shortDate(row.endsAt)}` : 'Dates not set'}</td><td className="r">{row.impactTrackingAvailable ? row.bookings : '—'}</td><td className="r">{row.impactTrackingAvailable ? money(row.sales || 0) : '—'}</td><td><Badge value={row.draft ? 'DRAFT' : row.active ? 'LIVE' : 'PAUSED'} /> {row.draft ? <button className="btn small" onClick={() => editDraft(row)}>Edit draft</button> : <button className="btn small" onClick={() => void toggle(row)}>{row.active ? 'Pause' : 'Resume'}</button>}</td></tr>)}</tbody></table>{!rows.length && <div className="empty">No promotions configured.</div>}</div>
    <div ref={formRef} className="partner-promotion-form-anchor"><Panel title={editingDraftId ? 'Edit promotion draft' : 'Create a promotion'}><p className="muted">Pick a type, set the discount, choose products and dates.</p><form className="partner-form-grid" onSubmit={(event) => void savePromotion(event)}>
      <div className="partner-promotion-types" role="group" aria-label="Promotion type">{typeOptions.map(([value,title,description]) => <button key={value} type="button" className={form.promotionType === value ? 'active' : ''} onClick={() => setForm({ ...form, promotionType: value })}><b>{title}</b><span>{description}</span></button>)}</div>
      <label><span>Promotion name</span><input required maxLength={120} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /><small>Only you see this.</small></label>
      {form.promotionType === 'FLAT_OFF' ? <label><span>Discount amount (INR)</span><input type="number" min="1" required value={form.discountAmount} onChange={(e) => setForm({ ...form, discountAmount: e.target.value })} /></label> : <label><span>Discount (%)</span><input type="number" min="1" max="100" required value={form.discountPercent} onChange={(e) => setForm({ ...form, discountPercent: e.target.value })} /></label>}
      {needsCondition && <label><span>{form.promotionType === 'EARLY_BIRD' ? 'Book at least this many days ahead' : form.promotionType === 'LAST_MINUTE' ? 'Book within this many hours' : 'Minimum group size'}</span><input type="number" min="1" step="1" required value={form.conditionValue} onChange={(e) => setForm({ ...form, conditionValue: e.target.value })} /></label>}
      <label><span>Bookable from (optional)</span><input type="date" value={form.bookingStartsAt} onChange={(e) => setForm({ ...form, bookingStartsAt: e.target.value })} /></label>
      <label><span>Bookable until (optional)</span><input type="date" value={form.bookingEndsAt} onChange={(e) => setForm({ ...form, bookingEndsAt: e.target.value })} /></label>
      <label><span>Valid on activity days</span><select value={weekdayPreset} onChange={(e) => { const value = e.target.value as typeof weekdayPreset; setWeekdayPreset(value); if (value === 'ALL') setForm({ ...form, validWeekdays: [] }); if (value === 'WEEKDAYS') setForm({ ...form, validWeekdays: ['MON','TUE','WED','THU','FRI'] }); if (value === 'WEEKENDS') setForm({ ...form, validWeekdays: ['SAT','SUN'] }); if (value === 'CUSTOM') setForm({ ...form, validWeekdays: [] }); }}><option value="WEEKDAYS">Weekdays only</option><option value="ALL">All days</option><option value="WEEKENDS">Weekends only</option><option value="CUSTOM">Custom days</option></select></label>
      {weekdayPreset === 'CUSTOM' && <fieldset className="partner-promotion-weekdays"><legend>Choose activity days</legend>{(['MON','TUE','WED','THU','FRI','SAT','SUN'] as const).map((day) => <label key={day}><input type="checkbox" checked={form.validWeekdays.includes(day)} onChange={(e) => setForm({ ...form, validWeekdays: e.target.checked ? [...form.validWeekdays, day] : form.validWeekdays.filter((value) => value !== day) })} />{day}</label>)}</fieldset>}
      <div className="partner-product-choices partner-product-choices-full"><span>Apply to</span><div>{products.map((p) => <label key={p.id}><input type="checkbox" checked={form.productIds.includes(p.id)} onChange={(e) => setForm({ ...form, productIds: e.target.checked ? [...form.productIds, p.id] : form.productIds.filter((id) => id !== p.id) })} /><span>{p.experienceName}</span></label>)}</div></div>
      <label><span>Max bookings (optional)</span><input type="number" min="1" placeholder="No limit" value={form.maxDiscountedBookings} onChange={(e) => setForm({ ...form, maxDiscountedBookings: e.target.value })} /></label>
      <label className="partner-checkbox-field"><input type="checkbox" checked={form.stackWithPlatform} onChange={(e) => setForm({ ...form, stackWithPlatform: e.target.checked })} /> Stack with platform offers?</label>
      <details className="partner-promotion-activity-dates" open><summary>Promotion activity date range (required)</summary><p className="muted">Controls which activity dates qualify. Bookable from/until above controls when customers can place the booking.</p><div><label><span>Activity date starts</span><input type="date" required value={form.startsAt} onChange={(e) => setForm({ ...form, startsAt: e.target.value })} /></label><label><span>Activity date ends</span><input type="date" required value={form.endsAt} onChange={(e) => setForm({ ...form, endsAt: e.target.value })} /></label></div></details>
      {weekdayPreset === 'CUSTOM' && !form.validWeekdays.length && <p className="muted partner-promotion-weekday-error" role="alert">Choose at least one activity day, or select All days.</p>}
      <div className="partner-promotion-submit"><button type="button" className="btn" disabled={busy || !form.productIds.length || !weekdaysValid} onClick={() => void persistPromotion(true)}>Save as draft</button><button type="submit" className="btn primary" disabled={busy || !form.productIds.length || !weekdaysValid}>{busy ? 'Saving…' : editingDraftId ? 'Publish promotion' : 'Create promotion'}</button>{editingDraftId && <button type="button" className="btn" onClick={() => { setEditingDraftId(''); setForm({ name: '', productIds: [], promotionType: 'PERCENTAGE_OFF', discountPercent: '10', discountAmount: '', conditionValue: '', startsAt: '', endsAt: '', bookingStartsAt: '', bookingEndsAt: '', validWeekdays: [], maxDiscountedBookings: '', stackWithPlatform: false }); }}>Cancel edit</button>}</div>
    </form></Panel>
      <div className="partner-dashboard-grid"><Panel title="Impact on the selected product"><div className="partner-promotion-preview"><b>{selectedPreview?.experienceName || 'Select a product to preview'}</b><div><span>Current starting price</span><strong>{currentPrice == null ? '—' : money(currentPrice)}</strong></div><div><span>With this promotion</span><strong>{promoPrice == null ? '—' : money(promoPrice)}</strong></div></div></Panel><Panel title="How customers see it"><div className="partner-promotion-preview"><b>{selectedPreview?.experienceName || 'Your activity listing'}</b><Badge value={form.name.trim() ? form.name.trim().toUpperCase().replaceAll(' ', '_') : 'PROMOTION'} /><p className="muted">The discount applies to the selected product dates and follows its current ticket rates.</p></div></Panel></div>
    </div>
  </>;
}

type Report = { id: string; name: string; type: string; format: string; createdAt: string; status: string; downloadUrl: string; error?: string | null };
type Schedule = { id: string; reportName: string; reportType: string; frequency: string; recipient: string; runTime: string; status: string };
type ReportSchedulesResponse = { items: Schedule[]; deliveryAvailable: boolean };
type VendorReview = { id: string; reviewerName?: string | null; rating: number; title?: string | null; comment?: string | null; reviewedAt: string; vendorReply?: string | null; repliedAt?: string | null; productName: string; source: string };
function reportDateValue(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
export function PartnerReportsPage() {
  const [reports, setReports] = useState<Report[]>([]); const [schedules, setSchedules] = useState<Schedule[]>([]); const [reportDeliveryAvailable, setReportDeliveryAvailable] = useState(false); const [reviews, setReviews] = useState<VendorReview[]>([]); const [replyDrafts, setReplyDrafts] = useState<Record<string, string>>({}); const [replyBusy, setReplyBusy] = useState(''); const [from, setFrom] = useState(() => { const date = new Date(); date.setDate(1); return reportDateValue(date); }); const [to, setTo] = useState(() => reportDateValue(new Date())); const [range, setRange] = useState('THIS_MONTH'); const [format, setFormat] = useState('XLSX'); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [scheduleForm, setScheduleForm] = useState({ reportName: '', reportType: 'BOOKINGS', frequency: 'WEEKLY', recipient: '', runTime: '09:00' });
  async function load() { try { const [r, s, v] = await Promise.all([api.request<Report[]>('/vendor/reports'), api.request<ReportSchedulesResponse>('/vendor/report-schedules'), api.request<VendorReview[]>('/vendor/reviews')]); setReports(r); setSchedules(s.items); setReportDeliveryAvailable(s.deliveryAvailable); setReviews(v); } catch (e) { setError(errorText(e)); } }
  useEffect(() => { void load(); }, []);
  useEffect(() => {
    if (!reports.some((report) => ['PENDING', 'PROCESSING'].includes(report.status))) return;
    const timer = window.setInterval(() => { void load(); }, 2000);
    return () => window.clearInterval(timer);
  }, [reports]);
  function chooseRange(value: string) {
    setRange(value); if (value === 'CUSTOM') return;
    const end = new Date(); end.setHours(0,0,0,0); const start = new Date(end);
    if (value === 'LAST_7_DAYS') start.setDate(start.getDate() - 6);
    else if (value === 'LAST_3_MONTHS') start.setMonth(start.getMonth() - 3);
    else if (value === 'FY_TO_DATE') { const fyStartMonth = 3; start.setFullYear(start.getMonth() < fyStartMonth ? start.getFullYear() - 1 : start.getFullYear(), fyStartMonth, 1); }
    else if (value === 'THIS_MONTH') start.setDate(1);
    setFrom(reportDateValue(start)); setTo(reportDateValue(end));
  }
  async function generate(type: string) { setBusy(true); setError(''); try { await api.request<Report>('/vendor/reports', { method: 'POST', body: JSON.stringify({ type, from: from || undefined, to: to || undefined, format }) }); await load(); } catch (e) { setError(errorText(e)); } finally { setBusy(false); } }
  async function schedule(event: React.FormEvent) { event.preventDefault(); setError(''); try { await api.request('/vendor/report-schedules', { method: 'POST', body: JSON.stringify(scheduleForm) }); setScheduleForm((current) => ({ ...current, reportName: '', recipient: '' })); await load(); } catch (e) { setError(errorText(e)); } }
  async function toggleSchedule(row: Schedule) { try { await api.request(`/vendor/report-schedules/${row.id}`, { method: 'PATCH', body: JSON.stringify({ status: row.status === 'ACTIVE' ? 'PAUSED' : 'ACTIVE' }) }); await load(); } catch (e) { setError(errorText(e)); } }
  async function reply(review: VendorReview) { const vendorReply = (replyDrafts[review.id] || review.vendorReply || '').trim(); if (!vendorReply) return; setReplyBusy(review.id); setError(''); try { await api.request(`/vendor/reviews/${review.id}/reply`, { method: 'PATCH', body: JSON.stringify({ vendorReply }) }); setReplyDrafts((current) => ({ ...current, [review.id]: '' })); await load(); } catch (e) { setError(errorText(e)); } finally { setReplyBusy(''); } }
  async function download(report: Report) { try { const blob = await api.blob(report.downloadUrl.replace(/^\/api/, '')); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `${report.name.toLowerCase().replaceAll(' ', '-')}.${report.format.toLowerCase()}`; a.click(); window.setTimeout(() => URL.revokeObjectURL(url), 0); } catch (e) { setError(errorText(e)); } }
  const reportCards: [string, string, string][] = [['BOOKINGS','Booking report','Service dates, products, booking status and amounts.'],['GUEST_MANIFEST','Guest manifest','Guest names, contact numbers and pickup details where supplied.'],['PAYOUTS','Payout statement','Booking-level settlement lines and payout status.'],['COMMISSION_INVOICES','Commission invoices','Issued and draft commission invoices with recorded GST.'],['PRODUCTS','Product report','Product names, destinations and statuses.'],['PRODUCT_PERFORMANCE','Product performance','Recorded views, bookings, guest counts and sales. Conversion is bookings divided by views in the selected period.'],['REVIEWS','Reviews','Ratings, comments and your replies.'],['CANCELLATIONS','Cancellations & refunds','Cancellation reasons, actual refunds, refund entitlement and status.'],['TDS_TCS_CERTIFICATES','TDS & TCS certificates','Recorded GST on commission, TDS 194-O and GST TCS by settlement line.']];
  return <><PageHeader title="Reports" description="Download any report for a date range, or have it emailed on a schedule." />{error && <ErrorBox error={error} />}<Panel title="Report filters"><div className="partner-form-grid"><label><span>Date range</span><select value={range} onChange={(e) => chooseRange(e.target.value)}><option value="LAST_7_DAYS">Last 7 days</option><option value="THIS_MONTH">This month</option><option value="LAST_3_MONTHS">Last 3 months</option><option value="FY_TO_DATE">Financial year to date</option><option value="CUSTOM">Custom dates</option></select></label>{range === 'CUSTOM' && <><label><span>From</span><input type="date" aria-label="Report date from" value={from} onChange={(e) => { setFrom(e.target.value); setRange('CUSTOM'); }} /></label><label><span>To</span><input type="date" aria-label="Report date to" value={to} onChange={(e) => { setTo(e.target.value); setRange('CUSTOM'); }} /></label></>}<label><span>Format</span><select aria-label="Report format" value={format} onChange={(e) => setFormat(e.target.value)}><option value="XLSX">Excel workbook</option><option value="CSV">CSV</option><option value="PDF">PDF</option></select></label></div></Panel><div className="partner-report-cards">{reportCards.map(([type, title, description]) => <button key={type} className="partner-report-card" disabled={busy} onClick={() => void generate(type)}><b>{title}</b><span>{description}</span><strong>{busy ? 'Queueing…' : 'Generate report →'}</strong></button>)}</div><Panel title="Reviews to reply to"><div className="table-wrap"><table><thead><tr><th>Review</th><th>Product</th><th>Rating</th><th>Date</th><th>Your reply</th><th /></tr></thead><tbody>{reviews.map((review) => <tr key={review.id}><td><b>{review.reviewerName || 'Traveller'}</b><small>{review.title || review.comment || '—'}</small></td><td>{review.productName}</td><td>{review.rating} / 5</td><td>{shortDate(review.reviewedAt)}</td><td><input aria-label={`Reply to ${review.reviewerName || 'review'}`} maxLength={2000} value={replyDrafts[review.id] ?? review.vendorReply ?? ''} onChange={(event) => setReplyDrafts((current) => ({ ...current, [review.id]: event.target.value }))} placeholder="Write a public reply" /></td><td><button className="btn small" disabled={replyBusy === review.id || !(replyDrafts[review.id] ?? review.vendorReply ?? '').trim()} onClick={() => void reply(review)}>{replyBusy === review.id ? 'Saving…' : review.vendorReply ? 'Update reply' : 'Reply'}</button></td></tr>)}</tbody></table></div>{!reviews.length && <div className="empty">No reviews have been received yet.</div>}</Panel><Panel title="Generated reports"><div className="table-wrap"><table><thead><tr><th>Report</th><th>Type</th><th>Format</th><th>Created</th><th>Status</th><th /></tr></thead><tbody>{reports.map((r) => <tr key={r.id}><td>{r.name}{r.error && <small>{r.error}</small>}</td><td>{r.type}</td><td>{r.format}</td><td>{shortDate(r.createdAt)}</td><td><Badge value={r.status} /></td><td><button className="btn small" disabled={r.status !== 'READY'} onClick={() => void download(r)}>{r.status === 'PENDING' || r.status === 'PROCESSING' ? 'Preparing…' : r.status === 'FAILED' ? 'Unavailable' : 'Download'}</button></td></tr>)}</tbody></table></div>{!reports.length && <div className="empty">No generated reports yet.</div>}</Panel><Panel title="Scheduled reports">{!reportDeliveryAvailable && <div className="alert info" role="status">Email delivery is not configured here. New schedules will be saved paused until report scheduling and email delivery are enabled.</div>}<form className="partner-form-grid" onSubmit={(event) => void schedule(event)}><label><span>Report name</span><input required maxLength={120} value={scheduleForm.reportName} onChange={(e) => setScheduleForm({ ...scheduleForm, reportName: e.target.value })} /></label><label><span>Report</span><select value={scheduleForm.reportType} onChange={(e) => setScheduleForm({ ...scheduleForm, reportType: e.target.value })}>{[['BOOKINGS','Bookings'],['GUEST_MANIFEST','Guest manifest'],['PAYOUTS','Payout statement'],['COMMISSION_INVOICES','Commission invoices'],['TDS_TCS_CERTIFICATES','TDS & TCS certificates'],['PRODUCTS','Products'],['PRODUCT_PERFORMANCE','Product performance'],['REVIEWS','Reviews'],['CANCELLATIONS','Cancellations & refunds']].map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></label><label><span>Frequency</span><select value={scheduleForm.frequency} onChange={(e) => setScheduleForm({ ...scheduleForm, frequency: e.target.value })}><option value="DAILY">Daily</option><option value="WEEKLY">Weekly</option><option value="MONTHLY">Monthly</option></select></label><label><span>Send to</span><input type="email" required value={scheduleForm.recipient} onChange={(e) => setScheduleForm({ ...scheduleForm, recipient: e.target.value })} /></label><label><span>Send time</span><input type="time" required value={scheduleForm.runTime} onChange={(e) => setScheduleForm({ ...scheduleForm, runTime: e.target.value })} /></label><div><button className="btn primary">Schedule report</button></div></form><div className="table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Frequency</th><th>Recipient</th><th>Time</th><th>Status</th><th /></tr></thead><tbody>{schedules.map((s) => <tr key={s.id}><td>{s.reportName}</td><td>{s.reportType}</td><td>{s.frequency}</td><td>{s.recipient}</td><td>{s.runTime}</td><td><Badge value={s.status} /></td><td><button className="btn small" disabled={s.status !== 'ACTIVE' && !reportDeliveryAvailable} title={s.status !== 'ACTIVE' && !reportDeliveryAvailable ? 'Enable scheduled email delivery before resuming.' : undefined} onClick={() => void toggleSchedule(s)}>{s.status === 'ACTIVE' ? 'Pause' : 'Resume'}</button></td></tr>)}</tbody></table></div>{!schedules.length && <div className="empty">No report schedules configured.</div>}</Panel></>;
}

type TeamMember = { id: string; email: string; fullName?: string | null; organizationRole?: string | null; active: boolean; lastLoginAt?: string | null };
type TeamData = { members: TeamMember[]; invitations: Array<{ id: string; email: string; role: string; status: string }> };
type NotificationPreferences = Record<'bookingEmail' | 'bookingWhatsapp' | 'bookingSms' | 'cancellationEmail' | 'cancellationWhatsapp' | 'cancellationSms' | 'payoutEmail' | 'payoutWhatsapp' | 'payoutSms' | 'documentExpiryEmail' | 'documentExpiryWhatsapp' | 'documentExpirySms' | 'reviewEmail' | 'reviewWhatsapp' | 'reviewSms' | 'twoStepVerification', boolean> & { delivery?: Record<string, boolean> };
const defaultNotificationPreferences: NotificationPreferences = { bookingEmail: true, bookingWhatsapp: true, bookingSms: true, cancellationEmail: true, cancellationWhatsapp: true, cancellationSms: true, payoutEmail: true, payoutWhatsapp: true, payoutSms: true, documentExpiryEmail: true, documentExpiryWhatsapp: true, documentExpirySms: true, reviewEmail: true, reviewWhatsapp: true, reviewSms: true, twoStepVerification: true };
export function PartnerSettingsPage({ canManageTeam = true }: { canManageTeam?: boolean }) {
  const [team, setTeam] = useState<TeamData>({ members: [], invitations: [] }); const [prefs, setPrefs] = useState<NotificationPreferences>(defaultNotificationPreferences); const [email, setEmail] = useState(''); const [role, setRole] = useState('VIEWER'); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [inviteLink, setInviteLink] = useState(''); const [inviteOpen, setInviteOpen] = useState(false);
  async function load() { try { const [t, p] = await Promise.all([api.request<TeamData>('/vendor/team'), api.request<NotificationPreferences>('/vendor/notification-preferences')]); setTeam(t); setPrefs(p); } catch (e) { setError(errorText(e)); } }
  useEffect(() => { void load(); }, []);
  async function invite(event: React.FormEvent) { event.preventDefault(); setError(''); setInviteLink(''); try { const result = await api.request<{ inviteToken: string }>('/vendor/team/invitations', { method: 'POST', body: JSON.stringify({ email, role }) }); setEmail(''); setInviteOpen(false); setNotice('Invitation created. Share this secure link with your teammate; it expires in 7 days.'); setInviteLink(`${window.location.origin}${vendorHref(`/register?teamInvite=${encodeURIComponent(result.inviteToken)}`)}`); await load(); } catch (e) { setError(errorText(e)); } }
  async function savePrefs(next: NotificationPreferences) { const previous = prefs; setPrefs(next); setNotice(''); try { await api.request('/vendor/notification-preferences', { method: 'PATCH', body: JSON.stringify(next) }); setNotice('Notification preferences saved.'); } catch (e) { setPrefs(previous); setError(errorText(e)); } }
  async function setMemberActive(member: TeamMember) { try { await api.request(`/vendor/team/members/${member.id}`, { method: 'PATCH', body: JSON.stringify({ active: !member.active }) }); await load(); } catch (e) { setError(errorText(e)); } }
  async function setMemberRole(member: TeamMember, organizationRole: string) { try { await api.request(`/vendor/team/members/${member.id}`, { method: 'PATCH', body: JSON.stringify({ organizationRole }) }); await load(); } catch (e) { setError(errorText(e)); } }
  const roleLabel = (value?: string | null) => ({ OWNER: 'Owner', CATALOGUE: 'Manager', OPERATIONS: 'Operations', FINANCE: 'Accounts', VIEWER: 'Viewer' } as Record<string, string>)[value || ''] || value || '—';
  const notificationEvents: Array<[string, string]> = [['booking','Booking updates'],['cancellation','Cancellations'],['payout','Payouts'],['documentExpiry','Document expiry'],['review','Product review']];
  return <><PageHeader title="Team & settings" description="Who can use this account, what they can do, and how you’re notified." action={canManageTeam && <button className="btn primary" type="button" aria-expanded={inviteOpen} aria-controls="team-invite-form" onClick={() => setInviteOpen((open) => !open)}>+ Invite team member</button>} />{error && <ErrorBox error={error} />}{notice && <div className="alert success" role="status">{notice}</div>}{inviteLink && <div className="partner-inline-form"><input aria-label="Team invitation link" readOnly value={inviteLink} /><button type="button" className="btn small" onClick={() => void navigator.clipboard?.writeText(inviteLink).then(() => setNotice('Invitation link copied.'))}>Copy invitation link</button></div>}{!canManageTeam && <p className="muted">Only workspace owners can invite members, change roles, or update account-wide notification settings.</p>}<Panel title="Team members">{canManageTeam && inviteOpen && <form id="team-invite-form" className="partner-inline-form" onSubmit={(e) => void invite(e)}><input id="team-invite-email" type="email" required aria-label="Team member email" placeholder="name@company.com" value={email} onChange={(e) => setEmail(e.target.value)} /><select aria-label="Workspace role" value={role} onChange={(e) => setRole(e.target.value)}><option value="OWNER">Owner</option><option value="CATALOGUE">Manager</option><option value="OPERATIONS">Operations</option><option value="FINANCE">Accounts</option><option value="VIEWER">Viewer</option></select><button className="btn primary">Send invitation</button><button type="button" className="btn" onClick={() => { setInviteOpen(false); setEmail(''); }}>Cancel</button></form>}<div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Last active</th><th /></tr></thead><tbody>{team.members.map((m) => <tr key={m.id}><td>{m.fullName || '—'}</td><td>{m.email}</td><td>{canManageTeam && m.organizationRole !== 'OWNER' ? <select aria-label={`Role for ${m.fullName || m.email}`} value={m.organizationRole || 'VIEWER'} onChange={(e) => void setMemberRole(m, e.target.value)}><option value="CATALOGUE">Manager</option><option value="OPERATIONS">Operations</option><option value="FINANCE">Accounts</option><option value="VIEWER">Viewer</option></select> : roleLabel(m.organizationRole)}</td><td>{m.lastLoginAt ? shortDate(m.lastLoginAt) : 'Never'}</td><td>{canManageTeam && m.organizationRole !== 'OWNER' && <button className="btn small" onClick={() => void setMemberActive(m)}>{m.active ? 'Remove' : 'Reactivate'}</button>}</td></tr>)}</tbody></table></div>{team.invitations.map((item) => <p key={item.id}>{item.email} · {roleLabel(item.role)} · {item.status}</p>)}</Panel><div className="partner-dashboard-grid"><Panel title="What each role can do"><div className="table-wrap"><table><thead><tr><th>Area</th><th>Owner</th><th>Manager</th><th>Operations</th><th>Accounts</th></tr></thead><tbody>{[['Products, rates, availability','✓','✓','—','—'],['Promotions','✓','✓','—','—'],['Accept bookings, redeem vouchers','✓','✓','✓','—'],['Payments & reports','✓','✓','Manifest only','✓'],['Bank, KYC, agreement','✓','—','—','View'],['Manage team','✓','—','—','—']].map((line) => <tr key={line[0]}>{line.map((cell, index) => index ? <td key={index}>{cell}</td> : <th key={index}>{cell}</th>)}</tr>)}</tbody></table></div></Panel><Panel title="Notifications"><div className="table-wrap"><table><thead><tr><th>Event</th><th>Email</th><th>WhatsApp</th><th>SMS</th></tr></thead><tbody>{notificationEvents.map(([key,label]) => <tr key={key}><th>{label}</th>{(['Email','Whatsapp','Sms'] as const).map((channel) => { const prefKey = `${key}${channel}` as keyof NotificationPreferences; const deliveryReady = prefs.delivery?.[prefKey] === true; return <td key={channel}><input type="checkbox" aria-label={`${label} via ${channel}`} checked={Boolean(prefs[prefKey])} disabled={!canManageTeam} title={deliveryReady ? '' : 'Not connected yet; this preference will apply when delivery is configured.'} onChange={(e) => void savePrefs({ ...prefs, [prefKey]: e.target.checked })} />{!deliveryReady && <span className="muted" title="Delivery provider is not configured"> Not connected</span>}</td>; })}</tr>)}</tbody></table></div><div className="partner-setting-toggle"><span>2-step verification · OTP on login from a new device</span><Badge value={prefs.twoStepVerification ? 'ON' : 'OFF'} /></div></Panel></div></>;
}

export function DeveloperNotesPage() {
  const hierarchy = ['Supplier · contract, KYC and payout', 'Product · content, media and location', 'Option · bookable variant', 'Ticket type · age band or unit', 'Rate · price by period and ticket type'];
  const operations = [['Availability', 'Service date, session, capacity and blackout'], ['Booking', 'Travellers, selected rate and price snapshot'], ['Voucher', 'Code, issue state and redemption status']];
  const endpoints = [['Account', 'POST /auth/register · POST /auth/login · POST /auth/vendor/login/request · POST /auth/vendor/login/verify · POST /auth/vendor/email/verify'], ['Profile & KYC', 'GET/PATCH /vendor/profile · GET/PATCH /vendor/onboarding · POST /vendor/documents/:type'], ['Catalogue', 'GET /products/listing · POST /products/drafts · PATCH /product-revisions/:id · POST /product-revisions/:id/submit'], ['Bookings', 'GET /vendor/bookings · POST /vendor/bookings/:id/confirm · POST /vendor/bookings/:id/reject · POST /vendor/manifest/bookings/:id/check-in'], ['Promotions', 'GET/POST /vendor/promotions · PATCH /vendor/promotions/:id'], ['Payments & reports', 'GET /settlements · GET/POST /vendor/reports · GET/POST /vendor/report-schedules'], ['Reviews', 'GET /vendor/reviews · PATCH /vendor/reviews/:id/reply · ADMIN POST /admin/vendors/:tenantId/reviews'], ['Team', 'GET /vendor/team · POST /vendor/team/invitations · PATCH /vendor/team/members/:id']];
  return <><PageHeader eyebrow="Not in product" title="Data model & API" description="Implementation notes for the vendor pages. Requests use the logged-in vendor tenant and its permissions." />
    <Panel title="Object hierarchy"><p className="muted">A product has bookable options and rates. A booking snapshots the product, rate and policy at purchase time.</p><div className="partner-data-flow">{hierarchy.map((item, index) => <span key={item}>{item}{index < hierarchy.length - 1 && <b aria-hidden="true">→</b>}</span>)}</div><div className="partner-data-branches">{operations.map(([name, detail]) => <div key={name}><b>{name}</b><span>{detail}</span></div>)}</div></Panel>
    <div className="partner-dashboard-grid"><Panel title="Vendor API (REST)"><div className="partner-notes">{endpoints.map(([name, routes]) => <div key={name}><b>{name}</b><span>{routes}</span></div>)}</div></Panel><Panel title="Build notes"><ul className="partner-build-notes"><li><b>Product edits</b> save into a working revision; submission starts review.</li><li><b>Bookings</b> use the canonical booking flow and retain their price snapshots.</li><li><b>Vendor settings</b> are tenant scoped and saved to PostgreSQL.</li><li><b>Vendor promotions</b> are applied during quote calculation and linked to booking price snapshots for impact reporting.</li><li><b>Scheduled reports</b> run in Asia/Kolkata time when VENDOR_REPORT_SCHEDULER_ENABLED=true and SMTP delivery settings are present.</li><li><b>Reviews</b> are stored by tenant and product; vendor replies are audited. WhatsApp/SMS delivery remains unconfigured.</li><li><b>Document expiry</b> sends 30/15/3-day email reminders and pauses products when required insurance or category-specific licences are invalid, resuming only auto-paused products after verification.</li></ul></Panel></div>
  </>;
}
